input.sparql:
PREFIX brick: <https://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://brickschema.org/schema/1.2/ref#>
SELECT ?series_id ?point_uri ?label WHERE {
  ?p brick:hasSubclass* brick:ElectricPower ;
     brick:hasPoint* ?x .
  ?point ref:hasTimeseriesId ?series_id .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?uri ?label WHERE {
  ?uri rdfs:label ?label .
  FILTER(CONTAINS(LCASE(?label), "supplyfan"))
}
